/**
 * Product reducers (Phase 4, D-06, D-09, D-10, D-12, D-13).
 *
 * Pure functions over SettingsData: they never mutate their input and they refuse any
 * change that would make the stored settings fail the version-3 validation on the next
 * load (a reserved or repeated name, a member that is already taken, a list over its
 * limit). The id is generated by the caller, never here, so the domain stays deterministic.
 * Member identity is `ruleMapKey(rfc, key)` in a Set, never an object keyed by RFC (Pitfall 8).
 */
import { ruleMapKey } from "./normalize";
import { comparableName } from "./schema";
import {
  LIMITS,
  SIN_CATEGORIA,
  type Product,
  type ProductMember,
  type SettingsData,
} from "./types";

export type ProductNameError = "empty" | "duplicate" | "reserved" | "too-long";

const RESERVED_NAME = comparableName("Sin categoría");

/**
 * Checks a typed product name (D-12). Trims it first. `exceptId` is the product being
 * renamed, which is left out of the duplicate check so only its case can change.
 */
export function validateProductName(
  settings: SettingsData,
  raw: string,
  exceptId: string | null,
): { ok: true; name: string } | { ok: false; reason: ProductNameError } {
  const name = raw.trim();
  if (name === "") return { ok: false, reason: "empty" };
  if (name.length > LIMITS.productName) return { ok: false, reason: "too-long" };
  const comparable = comparableName(name);
  if (comparable === RESERVED_NAME) return { ok: false, reason: "reserved" };
  const taken = settings.products.some(
    (product) => product.id !== exceptId && comparableName(product.name) === comparable,
  );
  if (taken) return { ok: false, reason: "duplicate" };
  return { ok: true, name };
}

/** `ruleMapKey(rfc, key)` of every member of every product (D-04: those descriptions are no longer free). */
export function productMemberKeys(settings: Pick<SettingsData, "products">): Set<string> {
  const keys = new Set<string>();
  for (const product of settings.products) {
    for (const member of product.members) keys.add(ruleMapKey(member.rfc, member.key));
  }
  return keys;
}

export type AcceptProductError = ProductNameError | "limit" | "members-taken" | "no-members";

/**
 * Turns an accepted suggestion into a product (D-06: no category; D-09: the members keep
 * rfc, normalized key, readable description and supplier name). Checks, in this order: the
 * name, that there is at least one member, that no member already belongs to a product or
 * is marked «No agrupar» (D-10, D-22), the limits of 2,000 products and 5,000 members in
 * total, and that the id is neither the reserved key nor already a product id. A member
 * repeated in the input is kept once. A refusal returns no settings at all.
 */
export function acceptProduct(
  settings: SettingsData,
  input: { name: string; members: readonly ProductMember[] },
  id: string,
):
  | { ok: true; next: SettingsData; product: Product }
  | { ok: false; reason: AcceptProductError } {
  const checked = validateProductName(settings, input.name, null);
  if (!checked.ok) return checked;

  const seen = new Set<string>();
  const members: ProductMember[] = [];
  for (const member of input.members) {
    const key = ruleMapKey(member.rfc, member.key);
    if (seen.has(key)) continue;
    seen.add(key);
    members.push({
      rfc: member.rfc,
      key: member.key,
      description: member.description,
      supplierName: member.supplierName,
    });
  }
  if (members.length === 0) return { ok: false, reason: "no-members" };

  const taken = productMemberKeys(settings);
  for (const mark of settings.ungroupedConcepts) taken.add(ruleMapKey(mark.rfc, mark.key));
  if (members.some((member) => taken.has(ruleMapKey(member.rfc, member.key)))) {
    return { ok: false, reason: "members-taken" };
  }

  const storedMembers = settings.products.reduce((sum, product) => sum + product.members.length, 0);
  if (
    settings.products.length >= LIMITS.products ||
    storedMembers + members.length > LIMITS.productMembers
  ) {
    return { ok: false, reason: "limit" };
  }

  if (id === SIN_CATEGORIA || settings.products.some((product) => product.id === id)) {
    return { ok: false, reason: "duplicate" };
  }

  const product: Product = { id, name: checked.name, categoryId: null, members };
  return { ok: true, next: { ...settings, products: [...settings.products, product] }, product };
}

// --- RED skeleton (Plan 04-07 Task 2): inert values so the tests import and fail on their assertions.

export function renameProduct(
  settings: SettingsData,
  id: string,
  raw: string,
): { ok: true; next: SettingsData } | { ok: false; reason: ProductNameError } {
  void settings;
  void id;
  void raw;
  return { ok: false, reason: "empty" };
}

export interface ProductSnapshot {
  product: Product;
  index: number;
}

export function deleteProduct(
  settings: SettingsData,
  id: string,
): { next: SettingsData; snapshot: ProductSnapshot } | null {
  void settings;
  void id;
  return null;
}

export function restoreProduct(settings: SettingsData, snapshot: ProductSnapshot): SettingsData {
  void snapshot;
  return { ...settings };
}

export type MemberUndo =
  | { kind: "member"; productId: string; member: ProductMember; index: number }
  | { kind: "product"; snapshot: ProductSnapshot; movedTo: string | null; member: ProductMember }
  | { kind: "moved"; fromId: string; toId: string; member: ProductMember; index: number };

export function removeProductMember(
  settings: SettingsData,
  productId: string,
  key: string,
): { next: SettingsData; undo: MemberUndo } | null {
  void settings;
  void productId;
  void key;
  return null;
}

export function moveProductMember(
  settings: SettingsData,
  fromId: string,
  key: string,
  toId: string,
): { next: SettingsData; undo: MemberUndo } | null {
  void settings;
  void fromId;
  void key;
  void toId;
  return null;
}

export function undoMemberChange(settings: SettingsData, undo: MemberUndo): SettingsData {
  void undo;
  return { ...settings };
}
